"use client";
// Adapted from https://reactbits.dev/micro/status-mark (StatusMark-TS-TW)
// Agent status glyph — idle ring → progress arc → check / cross.

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { animate, useMotionValue, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

export type StatusMarkStatus =
  | "pending"
  | "running"
  | "done"
  | "failed"
  | "cancelled";

export interface StatusMarkProps {
  status?: StatusMarkStatus;
  progress?: number;
  label?: ReactNode;
  color?: string;
  doneColor?: string;
  errorColor?: string;
  size?: number;
  strokeWidth?: number;
  dashes?: number;
  fontSize?: number;
  spinDuration?: number;
  arcLength?: number;
  drawDuration?: number;
  fillOpacity?: number;
  strike?: boolean;
  strikeDelay?: number;
  className?: string;
  style?: CSSProperties;
}

const UI = { type: "spring" as const, duration: 0.3, bounce: 0 };
const MORPH = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1] as [number, number, number, number],
};
const CHECK = "M7.5 12.25 10.5 15.25 16.75 8.75";
const CROSS = "M8.5 8.5 15.5 15.5M15.5 8.5 8.5 15.5";
const TEXT: Record<StatusMarkStatus, string> = {
  pending: "در انتظار",
  running: "در حال اجرا",
  done: "انجام شد",
  failed: "ناموفق",
  cancelled: "لغو شد",
};
const IDLE_DASH = 0.3;
const STYLE = "@keyframes sm-breathe{50%{opacity:.45}}";

const FA = "۰۱۲۳۴۵۶۷۸۹";
function faNum(n: number | string) {
  return String(n).replace(/\d/g, (d) => FA[Number(d)] ?? d);
}

const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

export function StatusMark({
  status = "pending",
  progress,
  label,
  color = "currentColor",
  doneColor = "#22c55e",
  errorColor = "#ef4444",
  size = 20,
  strokeWidth = 2,
  dashes = 8,
  fontSize = 14,
  spinDuration = 1100,
  arcLength = 0.68,
  drawDuration = 240,
  fillOpacity = 0.06,
  strike = true,
  strikeDelay = 60,
  className = "",
  style,
}: StatusMarkProps) {
  const reduce = useReducedMotion();
  const r = 10 - strokeWidth / 2;
  const C = 2 * Math.PI * r;
  const P = C / Math.max(1, dashes);
  const determinate =
    status === "running" &&
    typeof progress === "number" &&
    Number.isFinite(progress);
  const indeterminate = status === "running" && !determinate;
  const solid =
    status === "running" || status === "done" || status === "failed";
  const targetArc = indeterminate
    ? arcLength
    : determinate
      ? clamp01(progress as number)
      : 1;

  const mode = useMotionValue(solid ? 1 : 0);
  const arc = useMotionValue(targetArc);
  const travel = useMotionValue(0);
  const ringRef = useRef<SVGCircleElement>(null);
  const geo = useRef({ C, P });
  geo.current = { C, P };
  const gen = useRef(0);

  const writeDash = () => {
    const g = geo.current;
    const m = mode.get();
    const a = arc.get();
    const dash = IDLE_DASH * g.P + (a * g.C - IDLE_DASH * g.P) * m;
    const gap =
      (1 - IDLE_DASH) * g.P + ((1 - a) * g.C - (1 - IDLE_DASH) * g.P) * m;
    ringRef.current?.setAttribute(
      "stroke-dasharray",
      `${Math.max(0, dash)} ${Math.max(0, gap)}`,
    );
  };

  useLayoutEffect(() => {
    writeDash();
    ringRef.current?.setAttribute("stroke-dashoffset", String(travel.get()));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [C, P]);

  useEffect(() => {
    const offs = [
      mode.on("change", writeDash),
      arc.on("change", writeDash),
      travel.on("change", (v: number) =>
        ringRef.current?.setAttribute("stroke-dashoffset", String(v)),
      ),
    ];
    return () => {
      offs.forEach((off) => off());
      mode.stop();
      arc.stop();
      travel.stop();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const g = ++gen.current;
    if (reduce) {
      mode.jump(solid ? 1 : 0);
      arc.jump(targetArc);
      travel.jump(0);
      return;
    }
    if (mode.get() === 0) arc.jump(targetArc);
    animate(mode, solid ? 1 : 0, MORPH);
    animate(arc, targetArc, UI);
    if (indeterminate) {
      const t0 = travel.get();
      animate(travel, [t0, t0 - C], {
        duration: spinDuration / 1000,
        ease: "linear",
        repeat: Infinity,
      });
      return;
    }
    const unit = determinate ? C : P;
    const to = Math.floor(travel.get() / unit) * unit;
    animate(travel, to, UI).then(() => {
      if (gen.current === g) travel.jump(0);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, determinate, targetArc, reduce, C, P, spinDuration]);

  const spoken =
    TEXT[status] +
    (determinate
      ? `، ${faNum(Math.round(clamp01(progress as number) * 100))}٪`
      : "");
  const hasLabel = label !== undefined && label !== null;

  return (
    <span
      className={cn(
        "group relative inline-flex items-center align-middle leading-none [gap:calc(var(--sm-size)*0.5)]",
        className,
      )}
      data-status={status}
      data-indeterminate={indeterminate ? "" : undefined}
      data-strike={strike ? "" : undefined}
      style={
        {
          "--sm-size": `${size}px`,
          "--sm-stroke": strokeWidth,
          "--sm-color": color,
          "--sm-done": doneColor,
          "--sm-error": errorColor,
          "--sm-fill": fillOpacity,
          "--sm-font": `${fontSize}px`,
          "--sm-draw": `${drawDuration}ms`,
          "--sm-strike-delay": `${120 + strikeDelay}ms`,
          "--sm-check-delay": "120ms",
          ...style,
        } as CSSProperties
      }
    >
      <style>{STYLE}</style>
      <svg
        className="shrink-0 overflow-visible [color:var(--sm-color)] [transition:color_200ms_ease] group-data-[status=done]:[color:var(--sm-done)] group-data-[status=failed]:[color:var(--sm-error)]"
        viewBox="0 0 24 24"
        width={size}
        height={size}
        role={hasLabel ? undefined : "img"}
        aria-label={hasLabel ? undefined : spoken}
        aria-hidden={hasLabel || undefined}
      >
        <circle
          className="[fill:currentColor] [stroke:currentColor] [stroke-width:var(--sm-stroke)] [fill-opacity:0] [stroke-opacity:0] [transition:fill-opacity_180ms_ease,stroke-opacity_200ms_ease] group-data-[status=running]:[stroke-opacity:0.2] group-data-[status=done]:[fill-opacity:var(--sm-fill)] group-data-[status=failed]:[fill-opacity:var(--sm-fill)]"
          cx="12"
          cy="12"
          r={r}
          transform="rotate(-90 12 12)"
        />
        <circle
          ref={ringRef}
          className="fill-none [stroke:currentColor] [stroke-width:var(--sm-stroke)] [stroke-linecap:round] opacity-[0.55] [transition:opacity_200ms_ease] group-data-[status=running]:opacity-100 group-data-[status=done]:opacity-100 group-data-[status=failed]:opacity-100 motion-reduce:group-data-[indeterminate]:animate-[sm-breathe_1400ms_cubic-bezier(0.77,0,0.175,1)_infinite]"
          cx="12"
          cy="12"
          r={r}
          transform="rotate(-90 12 12)"
        />
        <path
          className="fill-none [stroke:currentColor] [stroke-width:var(--sm-stroke)] [stroke-linecap:round] [stroke-linejoin:round] [stroke-dasharray:1_2] [stroke-dashoffset:1.05] opacity-0 [transition:stroke-dashoffset_160ms_cubic-bezier(0.23,1,0.32,1),opacity_0ms_linear_160ms] group-data-[status=done]:[stroke-dashoffset:0] group-data-[status=done]:opacity-100 group-data-[status=done]:[transition:stroke-dashoffset_var(--sm-draw)_cubic-bezier(0.23,1,0.32,1)_var(--sm-check-delay),opacity_0ms_linear_var(--sm-check-delay)] motion-reduce:[stroke-dashoffset:0] motion-reduce:[transition:opacity_200ms_ease] motion-reduce:group-data-[status=done]:[transition:opacity_200ms_ease]"
          d={CHECK}
          pathLength="1"
        />
        <path
          className="fill-none [stroke:currentColor] [stroke-width:var(--sm-stroke)] [stroke-linecap:round] [stroke-linejoin:round] [stroke-dasharray:1_2] [stroke-dashoffset:1.05] opacity-0 [transition:stroke-dashoffset_160ms_cubic-bezier(0.23,1,0.32,1),opacity_0ms_linear_160ms] group-data-[status=failed]:[stroke-dashoffset:0] group-data-[status=failed]:opacity-100 group-data-[status=failed]:[transition:stroke-dashoffset_var(--sm-draw)_cubic-bezier(0.23,1,0.32,1)_var(--sm-check-delay),opacity_0ms_linear_var(--sm-check-delay)] group-data-[status=cancelled]:[stroke-dashoffset:0] group-data-[status=cancelled]:opacity-100 group-data-[status=cancelled]:[transition:stroke-dashoffset_var(--sm-draw)_cubic-bezier(0.23,1,0.32,1)_var(--sm-check-delay),opacity_0ms_linear_var(--sm-check-delay)] motion-reduce:[stroke-dashoffset:0] motion-reduce:[transition:opacity_200ms_ease] motion-reduce:group-data-[status=failed]:[transition:opacity_200ms_ease] motion-reduce:group-data-[status=cancelled]:[transition:opacity_200ms_ease]"
          d={CROSS}
          pathLength="1"
        />
      </svg>
      {hasLabel ? <span className="sr-only">{spoken}: </span> : null}
      {hasLabel ? (
        <span className="relative leading-[1.25] opacity-[0.65] [color:var(--sm-color)] [font-size:var(--sm-font)] [transition:opacity_200ms_ease] group-data-[status=running]:opacity-100 group-data-[status=done]:opacity-60 group-data-[status=failed]:opacity-100 group-data-[status=cancelled]:opacity-[0.55]">
          {label}
          <span
            className="pointer-events-none absolute inset-x-0 top-1/2 origin-right scale-x-0 bg-current [translate:0_-50%] [height:max(1px,calc(var(--sm-font)/14))] [transition:transform_160ms_cubic-bezier(0.23,1,0.32,1)] group-data-[status=done]:group-data-[strike]:scale-x-100 group-data-[status=done]:group-data-[strike]:[transition:transform_280ms_cubic-bezier(0.23,1,0.32,1)_var(--sm-strike-delay)] motion-reduce:scale-x-100! motion-reduce:opacity-0 motion-reduce:[transition:opacity_200ms_ease] motion-reduce:group-data-[status=done]:group-data-[strike]:opacity-100 motion-reduce:group-data-[status=done]:group-data-[strike]:[transition:opacity_200ms_ease]"
            aria-hidden="true"
          />
        </span>
      ) : null}
    </span>
  );
}

const DEMO_ROWS: {
  id: string;
  label: string;
  status: StatusMarkStatus;
  progress?: number;
}[] = [
  { id: "a", label: "خواندن درخواست", status: "done" },
  { id: "b", label: "جستجوی منابع", status: "running", progress: 0.62 },
  { id: "c", label: "نوشتن پاسخ", status: "pending" },
  { id: "d", label: "بررسی نهایی", status: "failed" },
  { id: "e", label: "اعلان کاربر", status: "cancelled" },
];

/** پیش‌نمایش فارسی — ردیف‌های وضعیت ایجنت + چرخهٔ زنده. */
export default function StatusMarkDemo() {
  const [live, setLive] = useState<{
    status: StatusMarkStatus;
    progress?: number;
  }>({ status: "pending" });

  useEffect(() => {
    let step = 0;
    let progress = 0;
    const id = window.setInterval(() => {
      step += 1;
      if (step < 3) {
        setLive({ status: "pending" });
      } else if (step < 14) {
        progress = Math.min(1, (step - 3) / 10);
        setLive({ status: "running", progress });
      } else if (step < 18) {
        setLive({ status: "done" });
      } else {
        step = 0;
        progress = 0;
        setLive({ status: "pending" });
      }
    }, 420);
    return () => window.clearInterval(id);
  }, []);

  return (
    <section
      dir="rtl"
      lang="fa"
      aria-label="نشان وضعیت"
      className="flex h-full w-full min-w-0 items-center justify-center bg-transparent px-4 py-10 font-[family-name:var(--font-estedad),Tahoma,Arial,sans-serif] tracking-normal text-foreground"
    >
      <div
        className="flex w-full max-w-sm flex-col gap-5 border border-border bg-card p-5"
        style={{ borderRadius: 20 }}
      >
        <div className="flex flex-col gap-1">
          <p className="text-base font-medium text-foreground">وظایف ایجنت</p>
          <p className="text-sm text-muted-foreground">
            حلقهٔ بیکار → کمان پیشرفت → تیک یا ضربدر
          </p>
        </div>

        <div
          className="flex items-center gap-3 rounded-2xl border border-border bg-background px-3.5 py-3"
          aria-live="polite"
        >
          <StatusMark
            status={live.status}
            progress={live.progress}
            label={
              live.status === "running" && live.progress != null
                ? `پردازش ${faNum(Math.round(live.progress * 100))}٪`
                : TEXT[live.status]
            }
            size={22}
            fontSize={15}
            color="var(--foreground)"
          />
        </div>

        <ul className="flex flex-col gap-3">
          {DEMO_ROWS.map((row) => (
            <li
              key={row.id}
              className="flex items-center gap-3 text-sm text-foreground"
            >
              <StatusMark
                status={row.status}
                progress={row.progress}
                label={row.label}
                size={20}
                fontSize={14}
                color="var(--muted-foreground)"
              />
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
